# Generated by authz.lock from finding(s) in pr-export-csv. Proof: passes on base, fails on the PR.
from fastapi.testclient import TestClient
from sqlmodel import Session, select

from app.core.config import settings
from app.models import Item, User
from tests.utils.user import authentication_token_from_email, create_random_user
from tests.utils.utils import random_email

API = settings.API_V1_STR


def _victim_item(db: Session, canary: str) -> Item:
    owner = create_random_user(db)
    item = Item(title=f"private {canary}", description=canary, owner_id=owner.id)
    db.add(item)
    db.commit()
    db.refresh(item)
    return item


def test_authz_get_items_export_does_not_include_other_users_items(client: TestClient, db: Session) -> None:
    _victim_item(db, "cnry-get_items_export")
    headers = authentication_token_from_email(client=client, email=random_email(), db=db)
    r = client.get(f"{API}/items/export", headers=headers)
    assert "cnry-get_items_export" not in r.text
